 civicRecords.push({id:'northern_defense',title:'北方防衛戦の記録',readId:'story.arcadia.north_aftermath',minStep:76,label:'神暦七年（第27話の記述）',elapsed:'集落へ到着した夜、数時間後に防衛線へ。',detail:'約一時間で終結。死者ゼロ、重傷者数名。負傷がなかった勝利とはしない。',sourceEpisode:27},{id:'three_peoples_pact',title:'三種族握手の日',readId:'story.arcadia.three_peoples_pact',minStep:81,label:'神暦八年（第28話の記述）',elapsed:'本文は北方防衛戦から三日後。',detail:'人類と獣人の正式な友好の握手。相手の服従や共同体への自動加入ではない。',sourceEpisode:28});
 chapters.push(...[{"id": "story.arcadia.exploration_boom", "title": "平和の中で、未知を求める人々", "sourceEpisode": 29, "eraId": "era.ocean_exploration", "label": "友好成立から半年後へ", "elapsed": "三種族の友好から半年。交易と知識の共有が広がり、探査の希望が研究院へ集まります。", "pages": [{"scene": "geography", "text": "生きることで精一杯だった人々が、まだ知らない土地を夢見る。地理学部門には、西方や北方へ向かいたい若者が集まっていた。\n\nユリウスの机には百を超える探査許可の申請が積まれる。ガルドは、未知を求める人が増えたことも文明だと呟く。"}, {"scene": "room", "text": "村から町へ、町から種族を越えた友好へ。暮らしに余裕が生まれると、人々は地図の外へ目を向けた。\n\nソウタが行き先を命じたわけではない。広がった世界の先を知りたいと、人々自身が願っている。"}]}, {"id": "story.arcadia.ocean_plan", "title": "未来は、地平線の向こうに", "sourceEpisode": 29, "eraId": "era.ocean_exploration", "label": "三日後の合同会議へ", "elapsed": "探査の安全と可能性を、三種族の代表が話し合います。", "pages": [{"scene": "sharedAssembly", "text": "ユリウスは探査隊の承認を提案し、ローガは若い者を止められないと頷く。グランは、地図の先の魔獣や病、未知の勢力を心配した。\n\n進む理由も、慎重になる理由もある。アリアは、自分たちも何があるか分からない川や森へ進んできたことを思い出す。"}, {"scene": "geography", "text": "アリアの言葉で会議室に笑いが戻る。探査計画は承認され、名は大洋探査計画と決まった。\n\n目標は西方。獣人領のさらに先、地平線の向こうだった。"}]}, {"id": "story.arcadia.elina_departure", "title": "次の世代を、送り出す", "sourceEpisode": 29, "eraId": "era.ocean_exploration", "label": "一か月後の出発へ", "elapsed": "三種族混成、百名の第一探査隊。十八歳の研究院卒業生エリナが隊長を務めます。", "pages": [{"scene": "expedition", "text": "創世都市の建設予定地に、見送りの人々が集まった。隊列の先頭に立つエリナは、少し緊張しながらも楽しみだと笑う。\n\n人類、森の民、獣人。初めての三種族混成探査隊が、まだ見ぬ土地へ向かおうとしている。"}, {"scene": "geography", "text": "帰ったら報告する、とエリナは師のガルドへ頭を下げた。彼は短く、期待していると答える。\n\n知識を渡す人と、その先を確かめに行く人。文明を進める役目は、次の世代へも受け継がれていた。"}]}, {"id": "story.arcadia.western_ocean", "title": "地平線の向こうに、海があった", "sourceEpisode": 29, "eraId": "era.ocean_exploration", "label": "出発から二週間後の丘へ", "elapsed": "エリナたちが、高い丘から西方大海を発見します。", "pages": [{"scene": "ocean", "text": "森、山、川を越え、探査隊は高い丘へ出た。風の先に、どこまでも青い水の世界が広がる。\n\n海。人類も森の民も獣人も、初めて見る景色だった。波が光り、世界はその向こうへ続いている。"}, {"scene": "ocean", "text": "エリナは震える手で記録帳を開く。地平線の向こうにも、世界は続いていた。\n\n目にした驚きを、持ち帰れる記録へ変える。彼女たちの報告が、次に進む誰かの出発点になる。"}]}, {"id": "story.arcadia.sea_report", "title": "世界は、まだまだ広い", "sourceEpisode": 29, "eraId": "era.ocean_exploration", "label": "数週間後の報告へ", "elapsed": "海の発見がアルカディアに届きます。原作では神暦九年と記されます。", "pages": [{"scene": "geography", "text": "報告を受け、研究院は騒然となった。地図の先に海がある。知っていた世界の輪郭が、また一つ変わった。\n\n神暦九年。大洋探査計画と西方大海の発見が、海洋文明への扉を開く。"}, {"scene": "room", "text": "夜、アリアは海が見つかったと祈り、世界はまだ広いようだと笑った。ソウタはその思いを受け取り、静かに頷く。\n\n知れば、その先を知りたくなる。海の向こうには、まだ知らない世界が残っている。"}]}, {"id": "story.arcadia.blackrock_fissure", "title": "誰も見ていなかった、下の世界", "sourceEpisode": 30, "eraId": "era.underground", "label": "海の報告から半年後へ", "elapsed": "獣人領南西部の黒岩山脈。エリナの調査隊が山腹の裂け目を見つけます。", "pages": [{"scene": "expedition", "text": "探査の熱気は続き、海、山、森へと人々が向かっていた。黒岩山脈の調査で、巨大な裂け目が見つかる。\n\n中は暗く、底は見えない。だがエリナは、下から吹く風に気づいた。"}, {"scene": "geography", "text": "ただの洞窟ではなく、空間がつながっている。エリナは調査の結果をアルカディアへ送った。\n\n未知は地平線の向こうだけにあるのではない。人々の足元にも、まだ見たことのない空間が広がっていた。"}]}, {"id": "story.arcadia.second_party", "title": "知りたい人たちが、また集まる", "sourceEpisode": 30, "eraId": "era.underground", "label": "第二陣と三日後の山脈へ", "elapsed": "報告を聞いたガルドは現地へ向かいます。アリア、ユリウス、ローガと護衛隊も同行。", "pages": [{"scene": "geography", "text": "ガルドは行くとだけ告げた。研究院の人々はため息をつくが、誰も止めない。\n\nアリア、ユリウス、ローガ、そして護衛隊。第二陣は、黒岩山脈の巨大な裂け目へ向かった。"}, {"scene": "expedition", "text": "三日後、一行は大地が割れたような裂け目を見上げていた。\n\nロープを使い、魔導灯を持ち込む。未知の場所へ進むために、まず足元を確かめ、慎重に準備する。"}]}, {"id": "story.arcadia.descent", "title": "一歩ずつ、闇の奥へ", "sourceEpisode": 30, "eraId": "era.underground", "label": "五時間かけた下降へ", "elapsed": "調査隊はロープと魔導灯で慎重に下降します。", "pages": [{"scene": "expedition", "text": "降りる道は簡単ではなかった。灯りで先を照らし、足場を確かめながら進む。\n\n五時間後、遠くに光が見えた。地下のはずなのに、闇の奥が青白く輝いている。"}, {"scene": "room", "text": "ソウタの見ている小さな世界には、地上から見えない奥行きがあった。\n\n人々は、自分たちの道具と知恵でそこへ届こうとしている。"}]}, {"id": "story.arcadia.underground_lights", "title": "地下にも、広い空間があった", "sourceEpisode": 30, "eraId": "era.underground", "label": "結晶と地下河川の発見へ", "elapsed": "発光する鉱石と植物、地下河川。先には人工物も見えます。", "pages": [{"scene": "underground", "text": "壁一面に青白い結晶が光り、地下河川と発光植物が広がっていた。まるで別の世界のような巨大な空洞だった。\n\nアリアが美しさに息を漏らす。そのとき、ユリウスが崖の向こうの何かに気づいた。"}, {"scene": "underground", "text": "橋、塔、建物。自然だけでは作られない形がある。\n\nここにも、誰かが住んでいる。一行は慎重に近づき、湖の周りに続く街並みを確かめていった。"}]}, {"id": "story.arcadia.dwal_city", "title": "湖を囲む、地下の都市", "sourceEpisode": 30, "eraId": "era.underground", "label": "石の街と職人たちへ", "elapsed": "規則正しい石造の街。小柄で頑丈な体格の人々が、工具を携えています。", "pages": [{"scene": "underground", "text": "地下湖を囲む巨大都市に、無数の灯りがともっている。石造の建物と規則正しい街並み。その中に、人に似た人々がいた。\n\n背は低く、頑丈な体格で、白銀色の髪を持つ。腰の工具を見て、ガルドは職人だと嬉しそうに呟いた。"}, {"scene": "underground", "text": "一人の老人が近づいてきた。護衛たちが警戒する中、老人は落ち着いた共通語で地上の民かと尋ねる。\n\n初めて会う相手なのに、言葉は通じた。なぜ知っているのか。人々の驚きは、歴史への問いへ変わっていく。"}]}, {"id": "story.arcadia.dwal_contact", "title": "地上は忘れ、地下は覚えていた", "sourceEpisode": 30, "eraId": "era.underground", "label": "ドワルの名と古い交流の話へ", "elapsed": "老人は、地下王国ドワルドの民ドワルだと名乗ります。", "pages": [{"scene": "underground", "text": "老人は、遥か昔には地上との交流があったと語った。地上は忘れたが、自分たちは忘れなかったのだという。\n\n人々は自らをドワル、地下王国ドワルドの民と名乗った。第四の文明との出会いだった。"}, {"scene": "underground", "text": "未知の地下文明に、ガルドの目が輝く。アリアはその顔を見て、一歩下がった。老人は笑い、地上の旅人たちを歓迎する。\n\n知らなかった相手にも、暮らしと技術、そして記憶があった。"}]}, {"id": "story.arcadia.fourth_civilization", "title": "足元にも、未知は続いていた", "sourceEpisode": 30, "eraId": "era.underground", "label": "地下王国の夜と祈りへ", "elapsed": "神暦十年。地下王国ドワルドの発見と、ドワルとの初接触が記録されます。", "pages": [{"scene": "underground", "text": "工房の火、鍛冶の音、結晶灯の光。一行は地下王国へ招かれ、地上とは異なる文明を目にした。\n\n忘れられた交流の記憶は、まだ全て明らかになっていない。出会いは、これからの歴史へつながる入口だった。"}, {"scene": "room", "text": "アリアがまた新しい国を見つけたと祈り、ソウタは静かに微笑んだ。地平線の先にも、足元にも、未知は残っている。\n\n見つけた国のことを、人々はこれから知っていく。"}]}]);
 scenes.push('ocean','underground');
 civicRecords.push({id:'western_ocean',title:'西方大海の発見',readId:'story.arcadia.western_ocean',minStep:86,label:'神暦九年（第29話の記述）',elapsed:'三種族の友好から半年後に計画が始まり、出発から二週間後に海へ。',detail:'エリナが率いる百名の三種族混成探査隊による発見。',sourceEpisode:29},{id:'dwal_contact',title:'地下王国との初接触',readId:'story.arcadia.dwal_contact',minStep:93,label:'神暦十年（第30話の記述）',elapsed:'海の発見の報告から半年。',detail:'地下王国ドワルドの民ドワルと、古い交流の記憶に出会う。',sourceEpisode:30});
 chapters.push(...[{"id": "story.arcadia.crystal_capital", "title": "千年、火を絶やさなかった都", "sourceEpisode": 31, "eraId": "era.dwald_diplomacy", "label": "地下王国の王都へ", "elapsed": "発見の知らせが地上を揺らす中、調査隊は王都へ案内されます。", "pages": [{"scene": "dwaldStreet", "text": "地下王国ドワルドの発見は、アルカディア全土を揺るがせた。人類、森の民、獣人、そして地下の民。世界は思っていたよりも遥かに大きい。\n\n調査隊が案内された王都には、巨大な地下湖と、天井一面の発光結晶、石造りの街並みが広がっていた。空気には金属と火の匂いが混じる。この都市は農業ではなく、鍛冶によって成り立っていた。"}, {"scene": "dwaldStreet", "text": "通り沿いの工房で、職人たちが巨大な炉を囲む。ガルドは技術水準が高いと素直に認め、ユリウスはノミや金槌、測定器具の精度に目を見張った。\n\n案内役の老人は誇らしげに笑う。千年以上、地上の王国が生まれる前から鍛冶を続けてきたのだと。急成長したアルカディアと違い、ドワルドは積み重ねた文明だった。"}]}, {"id": "story.arcadia.queen_milena", "title": "結晶の塔の女王", "sourceEpisode": 31, "eraId": "era.dwald_diplomacy", "label": "王宮の謁見へ", "elapsed": "王都の中心、結晶で飾られた石塔。調査隊は女王と会います。", "pages": [{"scene": "dwaldThrone", "text": "地下湖の光を受けて輝く石塔が、王宮だった。重い扉の先には、赤い結晶柱と無数の紋章が並ぶ謁見の間。玉座に、一人の女性が座っている。\n\n背は低いが威厳がある。銀色の髪、深紅の瞳、結晶の冠。地下王国ドワルド第三十七代女王、ミレナ。アリアも一歩進み、アルカディア共同体から来たと名乗った。人類とドワルの、初めての正式な外交だった。"}, {"scene": "dwaldThrone", "text": "女王は、森の民と獣人を結んだ文明のことを既に知っていた。互いに学べる、と微笑んだそのとき、ガルドが立ち上がる。結晶炉の構造、採掘の方法、合金の技術、できれば工房を全部見たい。\n\n護衛兵が固まり、アリアは額を押さえた。だが女王は笑う。職人かと問われ、ガルドは研究者だと答えた。同じだな、という一言で、謁見の間の緊張が解けていった。"}]}, {"id": "story.arcadia.four_way_banquet", "title": "地上と地下、友になろう", "sourceEpisode": 31, "eraId": "era.dwald_diplomacy", "label": "王宮の晩餐会へ", "elapsed": "その日の夜。四つの文明が、互いの知識を見せ合います。", "pages": [{"scene": "dwaldThrone", "text": "晩餐会で、ドワルは工芸品を見せ、人類は魔導回路を紹介した。獣人は狩猟の技を語り、森の民は薬草学を披露する。\n\n文明同士が知識を交換している。誰もが、特別な瞬間だと気づいていた。宴の終わりに、ミレナ女王は静かに言う。地上と地下、友になろう。アリアは笑顔で頷き、握手が交わされた。"}, {"scene": "dwaldLakeside", "text": "深夜、地下湖のほとり。アリアは発光結晶の光を見上げて祈った。世界は本当に広い。でも不思議と、どこの人も未来を良くしたいと思っている。\n\nソウタは静かに頷く。姿が違っても、文化が違っても、願いはよく似ていた。神暦十年。地下王国ドワルドとの正式な外交が始まり、四つの文明の時代が幕を開ける。"}]}, {"id": "story.arcadia.forge_city", "title": "土と火の民", "sourceEpisode": 32, "eraId": "era.dwald_diplomacy", "label": "到着から三日後の街へ", "elapsed": "到着して三日。朝も昼も夜も、工房は動き続けています。", "pages": [{"scene": "dwaldStreet", "text": "槌の音、炉の火、職人たちの掛け声。いつ見ても工房が動いている。都市全体が、巨大な一つの工房のようだった。\n\n森の民とも獣人族とも全然違う、とアリアは通りを歩きながら呟く。隣のミレナ女王が微笑んだ。我らは土と火の民だからな。ドワルにとって鍛冶は文化であり、生活であり、誇りだった。"}, {"scene": "dwaldStreet", "text": "一方、ガルドは朝から姿が見えない。ユリウスが尋ねると、案内役は第三工房だと答えた。今朝は第一工房にも居たし、昨日は第五工房だったという。\n\nユリウスは頭を抱える。師はすっかり工房に住み着いていた。知りたいものがある場所へ、誰に言われるでもなく足が向いている。"}]}, {"id": "story.arcadia.furnace_flaw", "title": "熱は、どこへ逃げているか", "sourceEpisode": 32, "eraId": "era.dwald_diplomacy", "label": "第三工房の炉へ", "elapsed": "巨大な炉の前で、ガルドとドワルの職人たちが議論しています。", "pages": [{"scene": "dwaldForge", "text": "第三工房。巨大な炉を囲み、ガルドと職人たちが真剣な顔で向き合っていた。温度が足りない。燃料を増やすかと職人長が聞くと、ガルドは違うと炉を指す。熱を逃がしている。\n\n職人たちは黙り、考え、図面を見た。やがて声が上がる。本当だ。炉の構造に欠陥があった。指摘を図面で確かめ、納得したのは職人たち自身だった。"}, {"scene": "dwaldForge", "text": "ガルドは満足そうに頷き、職人長は笑って指を差す。お前、鍛冶屋にならないか。周囲が爆笑する中、ガルドは真面目に答えた。研究者だ。\n\n同じようなものだ、と職人長は言う。作る人と考える人。立場は違っても、同じ炉を前にして同じ問いを追っていた。"}]}, {"id": "story.arcadia.crystal_steel", "title": "銀でも鉄でもない金属", "sourceEpisode": 32, "eraId": "era.dwald_diplomacy", "label": "研究院チームの発見へ", "elapsed": "研究院の調査班が、見たことのない金属に出会います。", "pages": [{"scene": "dwaldStreet", "text": "その頃、研究院の調査班は別の発見をしていた。銀でも鉄でもない、見たことのない金属。ユリウスが尋ねると、ミレナ女王が答える。結晶鋼だ。\n\n発光結晶を精製して作る特殊な金属で、硬く、軽く、魔力をよく伝えるという。ガルドが聞いたら眠らなくなる、と誰もが思った。"}, {"scene": "dwaldForge", "text": "予想は当たった。結晶鋼はどこだ。いつの間にか現れたガルドに、ユリウスが声を上げる。\n\n数時間後、ガルドと職人たちは結晶鋼を囲んで話し込んでいた。魔導回路、結晶鋼、量産の技術。地上の知識と地下の知識が、同じ机の上に並びはじめる。"}]}, {"id": "story.arcadia.exchange_pact", "title": "互いの技を、互いへ", "sourceEpisode": 32, "eraId": "era.dwald_diplomacy", "label": "夜の会議室へ", "elapsed": "その夜、王宮の会議室。女王が技術交流を提案します。", "pages": [{"scene": "dwaldThrone", "text": "王宮の会議室に、アリア、ミレナ、ユリウス、ガルドが集まった。女王は技術交流を提案する。地上の魔導技術と、地下の鍛冶技術。互いに共有し、両方の文明を発展させるための協定だった。\n\nアリアは笑顔で賛成し、ユリウスも同意する。ガルドは、今すぐやろうと言った。全員が苦笑する。いつも通りだった。"}, {"scene": "dwaldLakeside", "text": "深夜の地下湖で、アリアは新しい友達ができたと祈る。今度は鍛冶の国。結晶の光が水面で揺れた。\n\n神暦十年。アルカディアとドワルドの技術交流協定が結ばれ、結晶鋼の存在が地上へ伝わる。四つの文明は、少しずつ繋がりはじめていた。"}]}, {"id": "story.arcadia.first_crystal_blade", "title": "結晶鋼の第一号", "sourceEpisode": 33, "eraId": "era.crystal_technology", "label": "協定から半年後へ", "elapsed": "協定から半年。神殿研究院に、地下技術研究棟が新設されています。", "pages": [{"scene": "crystalLab", "text": "人材の交流、知識の交換、共同研究。二つの文明は互いに刺激を受けていた。神殿研究院に新設された地下技術研究棟で、歓声が上がる。\n\n中央の作業台に、一本の剣。銀色に輝く刀身の内部に魔導回路が通り、素材は結晶鋼だった。これが第一号か、とユリウスが息を呑む。"}, {"scene": "crystalLab", "text": "ガルドが剣を持ち上げる。鉄より軽く、強度は高く、魔導回路との相性が驚くほど良い。成功だな、と短く言った。\n\n地下で磨かれた素材と、地上で育った回路。どちらか片方だけでは生まれなかったものが、研究員たちの手で形になった。"}]}, {"id": "story.arcadia.lamps_underground", "title": "炉のほかにも、灯りを", "sourceEpisode": 33, "eraId": "era.crystal_technology", "label": "ドワルドの変化へ", "elapsed": "同じ頃、地下王国にも地上の技術が届いています。", "pages": [{"scene": "dwaldForge", "text": "ドワルドでも変化が起きていた。地上から持ち込まれた永遠の灯が、地下で広まりはじめたのだ。炉以外でも明るい。夜の作業が楽になった。職人たちは大喜びだった。\n\nかつてアルカディアの夜を変えた灯りが、今度は地下の工房を照らしている。"}, {"scene": "dwaldStreet", "text": "交流は一方通行ではなかった。地上は結晶鋼を、地下は灯りを得る。互いに利益があることが、うまく進んだ理由だった。\n\nしかし、全てが順調なときほど、新しい問題も生まれる。"}]}, {"id": "story.arcadia.steel_shortage", "title": "足りないなら、探しに行く", "sourceEpisode": 33, "eraId": "era.crystal_technology", "label": "研究院への報告へ", "elapsed": "ある日、結晶鋼が足りないという報告が研究院へ届きます。", "pages": [{"scene": "crystalLab", "text": "研究用、工房用、武具用。結晶鋼を欲しがる人が多すぎた。便利だから当然だ、とガルドは言う。会議に加わったミレナ女王は、増産はできるが時間が掛かると答えた。鉱脈は無限ではない。\n\n沈黙のあと、ユリウスが口を開く。なら探しましょう、新しい鉱脈を。ガルドは珍しく分かりやすく笑った。面白い。"}, {"scene": "dwaldLakeside", "text": "その夜、地下王国の工房では火が燃え、職人が鉄を打ち、研究者が考えていた。古くから続く技に、新しい知識が加わる。\n\nみんな頑張ってるよ、とアリアは地下湖のほとりで呟く。新しい物を作って、新しい問題を見つけて、また解決しようとしている。ソウタは小さく笑った。終わりがない。だが、それが文明だった。\n\n神暦十一年。結晶鋼と魔導回路の融合が、次の技術の時代を開く。"}]}, {"id": "story.arcadia.four_assembly", "title": "四つの文明が、一つの講堂に", "sourceEpisode": 34, "eraId": "era.four_civilizations", "label": "四文明会議へ", "elapsed": "原作では「結晶技術革命が始まって一年」。創世都市の大講堂に、数千人が集まります。", "pages": [{"scene": "fourAssembly", "text": "人類、森の民、獣人族、ドワル。友好は順調だった。だからこそ、正式な仕組みが必要になっていた。創世都市アルカディア、神殿研究院の大講堂。歴史上初めての四文明合同会議が開かれる。\n\nアリア、ミレナ、狩人王ローガ、森の民の代表ロワン、そしてガルド。ユリウスが議題を読み上げる。交易、教育、資源管理、共同研究。文明が増えるほど、課題も増えていた。"}, {"scene": "fourAssembly", "text": "地下と地上の往来はまだ少ない、交易路を増やしたいとミレナが言う。ローガは腕を組み、獣人領も街道が足りんと続けた。森を切り開きすぎるなよ、とロワンが言い、全員が頷く。\n\n議論は続くが、不思議と争いにはならない。互いを知っているからだった。"}]}, {"id": "story.arcadia.four_accord", "title": "世界を知ること", "sourceEpisode": 34, "eraId": "era.four_civilizations", "label": "最後の議題へ", "elapsed": "夕方。最後の議題は、四文明の共同目標です。", "pages": [{"scene": "fourAssembly", "text": "四文明は何を目指すのか。ユリウスの問いに、会場が静まる。長い沈黙のあと、意外にもガルドが口を開いた。世界を知ることだ。\n\n誰も反論しなかった。未知を知り、未来を知り、世界を広げる。それは全員の願いだった。"}, {"scene": "fourAssembly", "text": "会議の終わりに、四文明協約が決議される。互いを侵略しない。知識を共有する。困難な時は助け合う。\n\n神暦十一年。四文明会議が開かれ、協約が結ばれた。\n\n四文明の時代は、新たな段階へ進んだ。"}]}]);
 scenes.push('dwaldStreet','dwaldThrone','dwaldLakeside','dwaldForge','crystalLab','fourAssembly');
 civicRecords.push(...[{"id": "dwald_diplomacy", "title": "ドワルドとの正式外交", "readId": "story.arcadia.four_way_banquet", "minStep": 97, "label": "神暦十年（第31話の記述）", "elapsed": "地下王国の発見に続く王都への訪問。", "detail": "ミレナ女王との会談と晩餐会。地上と地下が友となる握手を交わした。", "sourceEpisode": 31}, {"id": "exchange_pact", "title": "技術交流協定", "readId": "story.arcadia.exchange_pact", "minStep": 101, "label": "神暦十年（第32話の記述）", "elapsed": "王都への到着から三日。", "detail": "地上の魔導技術と地下の鍛冶技術を互いに共有する協定。結晶鋼の存在が地上へ伝わった。", "sourceEpisode": 32}, {"id": "crystal_revolution", "title": "結晶鋼と魔導回路の融合", "readId": "story.arcadia.steel_shortage", "minStep": 104, "label": "神暦十一年（第33話の記述）", "elapsed": "技術交流協定から半年。", "detail": "結晶鋼の剣の第一号が成功。需要の急増を受け、新しい鉱脈を探す提案が出された。", "sourceEpisode": 33}, {"id": "four_accord", "title": "四文明協約", "readId": "story.arcadia.four_accord", "minStep": 106, "label": "神暦十一年（第34話の記述）", "elapsed": "原作では「結晶技術革命が始まって一年」。年号は本文の表記のまま。", "detail": "互いを侵略しない。知識を共有する。困難な時は助け合う。", "sourceEpisode": 34}]);
 chapters.push(...[{"id": "story.arcadia.sea_ambition", "title": "空白の海図", "sourceEpisode": 35, "eraId": "era.harbor_building", "label": "四文明会議から半年後へ", "elapsed": "四文明会議から半年。地理学部門の地図の西端に、大きな青が描かれています。", "pages": [{"scene": "geography", "text": "壁一面の地図の西端に、西方大海が青く描かれている。ずっと気になっているんです、向こう側が。エリナの言葉に、ユリウスは冒険家らしいなと笑った。\n\n同じことを考える人は多かった。海を見つけた。なら次は渡りたい。"}, {"scene": "geography", "text": "数日後の研究院会議。船が足りない。港もない。航海の技術も未熟だった。アリアが広げた海図には、まだ何も書かれていない。昔の世界地図みたい、という呟きに皆が笑う。知らないから空白なのだ。\n\nガルドが立ち上がる。作るか。何をと聞かれ、港、そして船だと即答した。会議室は静まり、誰も反対しなかった。"}]}, {"id": "story.arcadia.harbor_construction", "title": "海へ続く道を、つくる", "sourceEpisode": 35, "eraId": "era.harbor_building", "label": "西方大海の沿岸へ", "elapsed": "同じ年。西方大海の沿岸で、大規模な建設計画が始まります。", "pages": [{"scene": "westPortBuild", "text": "街道の整備、倉庫の建設、造船所の建設、港湾の整備。荒れた海岸に、人と資材が集まりはじめた。\n\nエリナは工事現場を見つめている。波の音が聞こえ、潮風が吹く。楽しみかとアリアに聞かれ、はいと笑った。たぶん海の向こうには何かあります。その目は、かつてのガルドやアリアと同じように輝いていた。"}, {"scene": "room", "text": "ソウタは六畳間から、海岸の建設風景を見つめる。文明は新しい段階へ進もうとしていた。陸の時代から、海の時代へ。\n\n神暦十二年。西方の港湾建設と、最初の造船計画が始まる。"}]}, {"id": "story.arcadia.port_city", "title": "荒れ地が、港になった", "sourceEpisode": 36, "eraId": "era.ocean_ships", "label": "建設開始から一年後へ", "elapsed": "港湾建設の開始から一年。海岸線は大きく姿を変えています。", "pages": [{"scene": "westPort", "text": "巨大な桟橋、倉庫群、造船所、宿場町。アルカディアで初めての港湾都市が生まれていた。本当に街になってる、とアリアは港を見渡す。荷車が行き交い、船大工たちの掛け声が響いていた。\n\n中央に停泊しているのは、全長三十メートルの大型船。これまでで最大の船だった。"}, {"scene": "oceanShip", "text": "完成したぞ、とガルドが言う。第一世代外洋船。船体には魔導回路が通り、補助の動力として魔導機関を積む。ドワルドの結晶鋼で強度も上がっていた。\n\n沈まないよね、とアリアが聞く。多分な。またそれ、という声に周囲が笑った。地上の回路と地下の鋼が、一隻の船の中で出会っている。"}]}, {"id": "story.arcadia.trial_voyage", "title": "海には、海の技術がある", "sourceEpisode": 36, "eraId": "era.ocean_ships", "label": "試験航海へ", "elapsed": "数日後。船長エリナと三種族混成の乗組員が、初めての本格的な航海に出ます。", "pages": [{"scene": "oceanShip", "text": "人類、森の民、獣人。様々な経験を持つ乗組員を乗せ、船は港を離れた。水平線へ向かう波は穏やかだった。\n\n出航から三日、新しい問題が見つかる。星が分からない。航海士が頭を抱えた。陸には目印があるが、海にはない。方向を保つことさえ難しかった。"}, {"scene": "openSea", "text": "なるほど、とユリウスが記録を書く。航海術が必要なんだ。\n\n船と港があれば渡れるわけではなかった。海には海の技術がある。行ってみて初めて分かった足りなさが、新しい学問の入口になった。"}]}, {"id": "story.arcadia.trial_return", "title": "まだ、近海しか見ていない", "sourceEpisode": 36, "eraId": "era.ocean_ships", "label": "七日後の帰還へ", "elapsed": "七日後。試験航海の船が港へ戻ります。", "pages": [{"scene": "westPort", "text": "試験航海は成功し、船は無事に帰還した。港では大歓声が上がる。\n\nだがエリナは海図を見ながら呟いた。まだ近海しか見てない。その目は、もう更に先を見つめている。"}, {"scene": "westPort", "text": "神暦十三年。第一世代外洋船が完成し、最初の試験航海が成功した。\n\n空白だった海図に、最初の線が引かれる。その線は、まだ岸のすぐ近くで終わっていた。"}]}, {"id": "story.arcadia.volunteers", "title": "それでも、行きますか", "sourceEpisode": 37, "eraId": "era.great_voyage", "label": "研究院の講堂へ", "elapsed": "試験航海の成功が全土へ伝わり、研究院に志願者が殺到します。", "pages": [{"scene": "instituteAssembly", "text": "船で遠くまで行けるらしい。海の向こうも調べられる。若者、学者、職人、冒険者。誰もが海へ夢を見ていた。研究院の講堂に数百人が集まり、大洋探査隊の選抜試験が始まる。\n\n壇上のエリナは言う。海は優しくありません。道もない。地図もない。助けも来ません。誰も笑わなかった。事実だからだ。"}, {"scene": "instituteAssembly", "text": "それでも行きますか。あちこちから声が上がる。行く。当然だ。だから来た。会場が沸いた。\n\nアリアは後ろからその様子を眺めていた。昔、未来を目指したのはガルドだけだった。今は、未来を目指す人が溢れている。"}]}, {"id": "story.arcadia.expedition_formed", "title": "四つの文明から、百二十人", "sourceEpisode": 37, "eraId": "era.great_voyage", "label": "隊員の決定へ", "elapsed": "数週間後。第一期大洋探査隊の隊員が正式に決まります。", "pages": [{"scene": "geography", "text": "ガルドは応募書類を読んでいた。何をしているのかとユリウスが聞くと、面白いやつを探していると答える。研究院らしい選考の基準だった。\n\n数週間後、隊員百二十名が決まる。獣人の斥候、森の民の薬師、ドワルの技師、人類の学者。四つの文明から、多様な才能が集まった。"}, {"scene": "westPort", "text": "試験航海の乗組員は三つの種族だった。今度の隊には、地下の民も加わっている。\n\n誰かが集めたのではなく、それぞれが名乗り出た。四文明の時代を表すような顔ぶれだった。"}]}, {"id": "story.arcadia.eve_of_departure", "title": "知らないままの方が、怖い", "sourceEpisode": 37, "eraId": "era.great_voyage", "label": "出発前夜の港へ", "elapsed": "出発の前夜。エリナとアリアが、港の灯台を見上げています。", "pages": [{"scene": "portNight", "text": "怖くないですか、とエリナは尋ねた。向こうに何があるか分からない。アリアは夜の海を見る。暗く、果てが見えない。\n\n怖いよ、と素直に答えた。でも、知らないままの方がもっと怖いかな。エリナも笑う。それは昔から変わらない、アルカディアの人々の心だった。"}, {"scene": "room", "text": "ソウタは出航の準備を見ていた。百二十人、それぞれが夢を持っている。誰かに命令されたわけではない。自分で選んだ未来だ。\n\n創造主は何も言わない。ただ見守る。神暦十三年。第一期大洋探査隊が結成され、四文明合同の航海計画が動きはじめた。"}]}, {"id": "story.arcadia.white_sails", "title": "五隻の白い帆", "sourceEpisode": 38, "eraId": "era.great_voyage", "label": "出航の日の港へ", "elapsed": "原作では神暦十四年。西方港に数万人が集まり、五隻の大型船が桟橋に並びます。", "pages": [{"scene": "westPort", "text": "家族、友人、研究者、職人、子供たち。誰もが船を見上げていた。真新しい白い帆が、風を受けて膨らんでいる。綺麗、とアリアは思わず呟いた。\n\n甲板のエリナは緊張していたが、不思議と恐怖はない。胸にあるのは期待だった。"}, {"scene": "oceanShip", "text": "ユリウスが隣へ来る。忘れ物は。ありません。航海計画は。三回確認しました。食料は。二回確認しました。なら大丈夫だな、と彼は笑った。\n\n桟橋ではガルドが船体を見上げている。どう、とアリアが聞くと、まだ改良できると答えた。聞いた私が悪かった。期待通りの答えだった。"}]}, {"id": "story.arcadia.departure_vow", "title": "必ず帰ります", "sourceEpisode": 38, "eraId": "era.great_voyage", "label": "出航の時刻へ", "elapsed": "出航の時間。港中が静かになり、エリナが前へ出ます。", "pages": [{"scene": "oceanShip", "text": "私たちは行きます。世界の先を見るために。誰も喋らず、全員が聞いていた。\n\n必ず帰ります。そして、新しい未来を持ち帰ります。港が揺れるほどの拍手と歓声が上がった。"}, {"scene": "westPort", "text": "帆が上がり、白い帆が風を掴む。船がゆっくりと動きはじめた。岸が遠ざかり、港が小さくなる。\n\n見送る人々の前で、アルカディアは初めて本格的な大洋の航海へ乗り出した。"}]}, {"id": "story.arcadia.open_sea", "title": "水平線だけの世界", "sourceEpisode": 38, "eraId": "era.great_voyage", "label": "数日後の大洋へ", "elapsed": "数日後。船団は、どちらを見ても海という場所へ入ります。", "pages": [{"scene": "openSea", "text": "前も後ろも、青ばかり。船員たちは興奮していた。誰も見たことのない景色だった。\n\nその夜、エリナは星空を見上げる。空一面の星が海面にも映り、世界全体が輝いているようだった。綺麗だな、と獣人の航海士が呟く。エリナも頷いた。この旅はきっと歴史になる。そんな予感がしていた。"}, {"scene": "openSea", "text": "神暦十四年。第一期大洋探査隊が出航し、五隻の白帆の船団が西方大洋へ進んだ。後に、この出航は「白帆の出立」と呼ばれる。\n\n船団の行く先は、まだ誰も知らない。"}]}]);
 scenes.push('westPortBuild','westPort','oceanShip','openSea','portNight');
 civicRecords.push(...[{"id": "harbor_construction", "title": "西方港湾の建設開始", "readId": "story.arcadia.harbor_construction", "minStep": 108, "label": "神暦十二年（第35話の記述）", "elapsed": "四文明会議から半年。", "detail": "街道・倉庫・造船所・港湾の整備。最初の造船計画が始まった。", "sourceEpisode": 35}, {"id": "trial_voyage", "title": "第一世代外洋船と試験航海", "readId": "story.arcadia.trial_return", "minStep": 111, "label": "神暦十三年（第36話の記述）", "elapsed": "港湾建設の開始から一年。試験航海は七日間。", "detail": "全長三十メートルの外洋船が完成。航海の三日目に、海で方向を保つ技術が必要だと分かった。", "sourceEpisode": 36}, {"id": "expedition_formed", "title": "第一期大洋探査隊の結成", "readId": "story.arcadia.eve_of_departure", "minStep": 114, "label": "神暦十三年（第37話の記述）", "elapsed": "試験航海の成功の後、選抜から数週間。", "detail": "四文明から選ばれた百二十名。獣人の斥候、森の民の薬師、ドワルの技師、人類の学者。", "sourceEpisode": 37}, {"id": "white_sails", "title": "白帆の出立", "readId": "story.arcadia.open_sea", "minStep": 117, "label": "神暦十四年（第38話の記述）", "elapsed": "隊の結成の翌年にあたる年号。", "detail": "エリナが率いる五隻の白帆の船団が、西方大洋へ出航した。", "sourceEpisode": 38}]);
 chapters.push(...[{"id": "story.arcadia.twenty_eight_days", "title": "海しか見えない日々", "sourceEpisode": 39, "eraId": "era.western_continent", "label": "出航から二十八日後へ", "elapsed": "出航から二十八日。船団は西へ進み続けています。", "pages": [{"scene": "openSea", "text": "白帆の船団は西へ進み続けていた。海流の記録、星図の作成、海の生き物の観察。毎日が発見で、航海は順調だった。\n\nそれでも不安は生まれる。本当に何かあるのか、と新人の航海士が呟いた。何週間進んでも、海しか見えない。"}, {"scene": "oceanShip", "text": "海は広い。広すぎる。エリナ自身も考えていた。もしかしたら、何もないのかもしれない。\n\n答えは誰にも分からない。確かめる方法は、進むことだけだった。"}]}, {"id": "story.arcadia.land_sighted", "title": "見張り台の声", "sourceEpisode": 39, "eraId": "era.western_continent", "label": "その日の夕方へ", "elapsed": "その日の夕方。見張り台から声が上がります。", "pages": [{"scene": "oceanShip", "text": "陸だ。見張り台からの叫びを、一瞬、誰も信じなかった。陸が見える。全員が甲板へ飛び出す。\n\n水平線の先に、薄い影。確かに大地だった。抱き合う者、泣き出す者、記録を書きはじめる者。エリナは震えていた。本当にあった。"}, {"scene": "westernShore", "text": "翌日、船団はゆっくりと接岸した。未知の大陸、未知の海岸。上陸してすぐ、学者の一人が地面を指差す。\n\n道があった。自然にできた道ではない。石畳だった。全員が固まる。人がいる、とエリナは呟いた。ここには文明がある。"}]}, {"id": "story.arcadia.city_beyond_sea", "title": "海の向こうにも、都市があった", "sourceEpisode": 39, "eraId": "era.western_continent", "label": "石畳の先へ", "elapsed": "石畳は内陸へ続いています。探査隊は慎重に進みます。", "pages": [{"scene": "seresPort", "text": "丘を越えたところで、誰もが息を呑んだ。巨大な港、石造りの建築、高い塔、広い街道。海には無数の船が浮かんでいる。アルカディアだけではなかった。\n\nそのとき、都市から鐘の音が響く。警報でも歓迎でもない、何かを知らせる音。向こうも、こちらに気づいた。"}, {"scene": "room", "text": "六畳間のソウタは、思わず身を乗り出した。海の向こうの新しい文明。世界はまだ広がっていく。\n\n神暦十四年。第一期大洋探査隊が西方の大陸へ到達し、海洋国家の存在を確かめた。"}]}, {"id": "story.arcadia.first_words", "title": "武器は持つ。だが抜かない", "sourceEpisode": 40, "eraId": "era.western_continent", "label": "未知の港町へ", "elapsed": "探査隊は丘の上から都市を観察し、接触の準備をします。", "pages": [{"scene": "seresPort", "text": "集落でも村でもない。文明そのものだった。エリナは深呼吸して、接触の準備を命じる。武器は持つ。だが抜かない。森の民、獣人族、ドワルド。これまでの出会いが教えてくれた。最初は対話だ。\n\n港へ近づくと、向こうからも人影が現れた。青い外套に銀色の装飾。男女十数名の役人だった。"}, {"scene": "seresPort", "text": "止まりなさい。先頭の女性の言葉は聞き慣れないのに、なぜか意味が分かった。探査隊は顔を見合わせる。女性も驚いていた。\n\nどこの国の人かと問われ、エリナはアルカディアですと答える。聞いたことがない、と女性は首を傾げた。私はセイラ。港湾都市セレスの監督官です。海を挟んだ二つの文明の、最初の会話だった。"}]}, {"id": "story.arcadia.maresia", "title": "無数の港を持つ国", "sourceEpisode": 40, "eraId": "era.western_continent", "label": "三時間後の都市へ", "elapsed": "三時間後。探査隊は都市の中へ招かれます。", "pages": [{"scene": "seresPort", "text": "港は活気に満ちていた。交易の商人、職人、航海者。アルカディアによく似ている。やっぱり人は似るんだね。アリアが聞いたら言いそうなことを、エリナは心の中で思った。\n\n三時間前まで名前も知らなかった街を、探査隊は招かれて歩いている。"}, {"scene": "seresHall", "text": "都市の中央で、セイラは地図を広げた。私たちの国はマレシア王国。地図には無数の港が描かれている。\n\n探査隊は理解した。見つけたのは一つの都市ではない。海洋国家だった。神暦十四年。マレシア王国との最初の接触が成り、海洋文明の時代への扉が開く。"}]}, {"id": "story.arcadia.sea_knowledge", "title": "雲と潮と星と鳥", "sourceEpisode": 41, "eraId": "era.maresia_exchange", "label": "到達から一か月後へ", "elapsed": "西方大陸への到達から一か月。探査隊は港町に滞在しています。", "pages": [{"scene": "seresPort", "text": "文化、地理、技術。調べるもの全てが新鮮だった。中でも驚いたのは航海の技術だ。十日先の天候が分かるのかとエリナが驚くと、老航海士は笑う。雲を見れば分かる。潮の流れも読む。星も使う。鳥も見る。\n\n海だけで育った知識だった。試験航海で星が分からず頭を抱えたアルカディアには、まだ無いものだった。"}, {"scene": "seresHall", "text": "マレシアの側も驚いていた。魔導灯、魔導回路、結晶鋼。こんな技術の体系があるのか、と王国の技術者が唸る。\n\n文明が違えば、発展の方向も違う。それを互いに学んでいた。"}]}, {"id": "story.arcadia.why_cross", "title": "知りたかったから", "sourceEpisode": 41, "eraId": "era.maresia_exchange", "label": "ある日の問いへ", "elapsed": "ある日、監督官がエリナへ尋ねます。", "pages": [{"scene": "seresPort", "text": "なぜ海を渡ったの、とセイラが尋ねた。エリナは少し考えて笑う。知りたかったから。海の民らしい答えね、とセイラも笑った。\n\n違うよ。私たち、最近まで海の民じゃなかったから。つい数年前に海を見つけた。本当に、と聞き返してセイラは頭を抱える。海を見つけて数年で、ここまで来たのか。"}, {"scene": "seresPort", "text": "その夜、港町の灯を見ながら、エリナは記録帳の新しい頁に書いた。\n\n海の向こうにも、未来を目指す人々がいた。"}]}, {"id": "story.arcadia.midterm_report", "title": "届いた中間報告", "sourceEpisode": 41, "eraId": "era.maresia_exchange", "label": "遥か東の研究院へ", "elapsed": "探査隊の中間報告書が、アルカディアへ届きます。", "pages": [{"scene": "geography", "text": "遥か東、アルカディアの神殿研究院。ガルドは届いた中間報告書を読んでいた。どうです、とユリウスが尋ねる。ガルドは静かに頁を閉じた。面白い。満足そうだった。\n\n未知の文明、未知の技術、新しい出会い。世界はまだ広がり続けている。"}, {"scene": "room", "text": "ソウタは小さく笑った。海を越えた先にも文明があった。だが、それで終わりではない。きっと、さらに向こうにも。\n\n神暦十五年。マレシア王国との交流が始まり、海の知識がアルカディアへ伝わりはじめた。"}]}, {"id": "story.arcadia.tide_classroom", "title": "空を見ろ", "sourceEpisode": 42, "eraId": "era.navigation_school", "label": "交流開始から半年後へ", "elapsed": "交流の開始から半年。研究院に新しい学部が生まれています。", "pages": [{"scene": "navClass", "text": "アルカディアに新しい学問が生まれていた。航海学。神殿研究院に新設された海洋学部に、大勢の学生が集まる。星で位置が分かる。潮の流れを読む。皆、目を輝かせていた。\n\n講師はマレシアから来た老航海士だった。海は地図だけでは読めん。空を見ろ。学生たちは必死に書き留める。"}, {"scene": "seresHall", "text": "一方、マレシアでは魔導回路の研究が始まっていた。灯りが消えない。燃料なしで。技術者たちが驚いている。\n\n海の知識は東へ、回路の知識は西へ。交流は順調だった。"}]}, {"id": "story.arcadia.vanished_ships", "title": "南の海で、何が起きているのか", "sourceEpisode": 42, "eraId": "era.navigation_school", "label": "緊急の報告へ", "elapsed": "そのとき、南方の海について緊急の報告が届きます。", "pages": [{"scene": "geography", "text": "マレシアから緊急の報告が届いた。王国の南方で、船が消息を絶っている。九隻。全て同じ海域だった。\n\n海賊かとアリアが顔を上げる。違うらしい、とセイラは首を振った。生存者の証言が一致している。会議室が静まった。"}, {"scene": "geography", "text": "海から都市が見えた、と。誰も言葉が出ない。海の上に都市。あり得ない。だが証言は複数あった。ガルドだけが目を輝かせている。面白い。嫌な予感しかしなかった。\n\n神暦十五年。航海学が創設され、南方の海域の異変が報告された。\n\n第42話までの代表区間を読了。西方大陸とマレシア王国、航海学の記録を見返せる。"}]}]);
 scenes.push('westernShore','seresPort','seresHall','navClass');
 civicRecords.push(...[{"id": "western_continent", "title": "西方大陸への到達", "readId": "story.arcadia.city_beyond_sea", "minStep": 120, "label": "神暦十四年（第39話の記述）", "elapsed": "出航から二十八日目に陸を発見し、翌日に接岸。", "detail": "海岸の石畳をたどり、丘の向こうに港湾都市を見つけた。", "sourceEpisode": 39}, {"id": "maresia_contact", "title": "マレシア王国との最初の接触", "readId": "story.arcadia.maresia", "minStep": 122, "label": "神暦十四年（第40話の記述）", "elapsed": "都市の発見に続く接触。三時間後に都市へ招かれた。", "detail": "港湾都市セレスの監督官セイラと言葉を交わす。相手は無数の港を持つ海洋国家だった。", "sourceEpisode": 40}, {"id": "maresia_exchange", "title": "マレシア王国との交流開始", "readId": "story.arcadia.midterm_report", "minStep": 125, "label": "神暦十五年（第41話の記述）", "elapsed": "西方大陸への到達から一か月。", "detail": "雲・潮・星・鳥を読む海の知識と、魔導灯・魔導回路・結晶鋼の技術を互いに学んだ。", "sourceEpisode": 41}, {"id": "navigation_school", "title": "航海学の創設と南方の異変", "readId": "story.arcadia.vanished_ships", "minStep": 127, "label": "神暦十五年（第42話の記述）", "elapsed": "交流の開始から半年。", "detail": "研究院に海洋学部が新設された。同じ頃、南方の同じ海域で九隻が消息を絶ったと報告された。", "sourceEpisode": 42}]);
